example_item.example_item_data:
folder = [tempdir(), createGUID()];
mkdir(folder);
filename = fullfile(folder, 'data.tar.xz');
t = nelson.io.tar.open(filename, 'w');
t.write('notes/hello.txt', 'Hello archive');
t.write('data.bin', uint8(1:100));
t.close();
a = nelson.io.archive.open(filename);
a.Format
a.Compression
T = a.entries()
a.readtext('notes/hello.txt')
filenames = a.extract(fullfile(folder, 'out'))
a.close();
filenames = nelson.io.archive.extract(filename, fullfile(folder, 'out2'))
rmdir(folder, 's');
